def getmask(g):
 cells=[(r,c) for r,row in enumerate(g) for c,v in enumerate(row) if v==3]
 return min(r for r,c in cells),max(r for r,c in cells),min(c for r,c in cells),max(c for r,c in cells)
def transform_simple(g):
 r0,r1,c0,c1=getmask(g)
 h,w=len(g),len(g[0])
 # choose symmetrical reflection that is clean, prioritize fewer 3s
 candidates=[]
 for mode in ('ud','lr','rot'):
  out=[]
  for r in range(r0,r1+1):
   row=[]
   for c in range(c0,c1+1):
    rr,cc={'ud':(h-1-r,c),'lr':(r,w-1-c),'rot':(h-1-r,w-1-c)}[mode]
    row.append(g[rr][cc])
   out.append(row)
  candidates.append((sum(v==3 for row in out for v in row), mode, out))
 return min(candidates,key=lambda x:x[0])[2]
